            if c_v.value is None and c_f.value is None:
                continue
            val = c_v.value
            if val is None:
                val = "<no cached value>"
            f = ""
            if isinstance(c_f.value, str) and c_f.value.startswith("="):
                f = f"  formula={c_f.value}"
            print(f"{c_v.coordinate}: {val!r}{f}")
            if isinstance(c_v.value, (int, float)):
                numeric.append((c_v.coordinate, c_v.value))
    sheet_total = sum(v for _, v in numeric)
    ALL_NUMERIC[ws_v.title] = (numeric, sheet_total)
    print(f"[all numeric cells on sheet: {sheet_total}]")

