    ws = wbv[name]
    rows = [[c for c in row] for row in ws.iter_rows()]
    header_row_idx = None
    for i, row in enumerate(rows[:5]):
        if any(isinstance(c.value, str) and c.value.strip() for c in row):
            header_row_idx = i
            break
    if header_row_idx is not None:
        header = rows[header_row_idx]
        amt_col = None
        label_col = None
        for j, c in enumerate(header):
            if c.value is None:
                continue
            s = str(c.value).lower()
            if any(k in s for k in ("amount", "cost", "expense", "budget", "value", "actual", "spent", "total")):
                if amt_col is None:
                    amt_col = j
            if label_col is None and s:
                label_col = j
        if amt_col is not None:
            total = 0.0
            for row in rows[header_row_idx + 1:]:
                label_cell = row[label_col].value if label_col is not None and label_col < len(row) else None
                amt_cell = row[amt_col].value if amt_col < len(row) else None
                label_s = str(label_cell).lower() if label_cell is not None else ""
                if any(k in label_s for k in ("total", "sum", "grand")):
                    continue
                if isinstance(amt_cell, (int, float)):
                    total += amt_cell
            print(f"{name}: sum of '{header[amt_col].value}' column (rows below header, excluding total rows) = {total}")

